INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM205C8A2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A sector of a circle with radius $15$ has an arc length of $8\\pi$. What is the central angle of the sector, in degrees?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '96', ARRAY['96'], E'The arc length formula is $s = \\frac{\\theta}{360} \\times 2\\pi r$. Substituting $s = 8\\pi$ and $r = 15$: $8\\pi = \\frac{\\theta}{360} \\times 30\\pi$. Dividing both sides by $\\pi$: $8 = \\frac{\\theta}{360} \\times 30 = \\frac{30\\theta}{360} = \\frac{\\theta}{12}$. Therefore $\\theta = 96°$. A common error is using the area formula $A = \\frac{\\theta}{360} \\pi r^2$ instead, which would yield a different angle. Another error is forgetting to include the factor of $2$ in $2\\pi r$, giving $\\frac{\\theta}{360} \\times 15\\pi = 8\\pi$, which yields $\\theta = 192°$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20AJW6R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'grid_in', E'A line of best fit for a data set is given by \\(y = 2.3x + 14\\). Using this model, what is the predicted value of \\(y\\) when \\(x = 9\\)?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '34.7', ARRAY['34.7'], E'Substituting x = 9 into the equation gives y = 2.3(9) + 14 = 20.7 + 14 = 34.7. A common error is computing 2.3 × 9 as 18.7 (arithmetic slip) and getting 32.7 instead. Another error is forgetting to add the constant 14, yielding only 20.7.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM216HG5N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'Researchers surveyed a random sample of $1{,}200$ adults in a state and found that $41\\%$ approved of a new transit policy, with a margin of error of $\\pm 2.8\\%$. A second random sample of $300$ adults from the same state found that $44\\%$ approved, with a margin of error of $\\pm 5.6\\%$. Which of the following best explains why the second survey has a larger margin of error?', NULL, $lyceon_json$[{"key":"A","text":"The second sample's approval percentage is farther from $50\\%$."},{"key":"B","text":"The second sample is smaller, which increases the variability of the estimate."},{"key":"C","text":"The second survey was conducted later, so opinions had shifted."},{"key":"D","text":"The second sample's approval percentage is higher, which always increases the margin of error."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error is primarily determined by sample size: smaller samples produce more variable estimates and therefore wider margins of error. The second sample ($300$) is one-quarter the size of the first ($1{,}200$), which is why its margin of error ($\\pm 5.6\\%$) is roughly double. The option about the percentage being farther from $50\\%$ is factually incorrect — $44\\%$ is closer to $50\\%$ than $41\\%$ is — and proximity to $50\\%$ has only a minor effect compared to sample size. The option about opinions shifting confuses a change in the point estimate with a change in precision. The option claiming a higher percentage always increases the margin of error is false; margins of error are maximized near $50\\%$ and decrease as the proportion moves toward $0\\%$ or $100\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21E6L1M', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A deck contains $40$ cards: $10$ are red and marked "Win," $6$ are red and marked "Lose," $9$ are blue and marked "Win," and $15$ are blue and marked "Lose." Two cards are drawn at random without replacement. Given that the first card drawn is blue and marked "Win," what is the probability that the second card drawn is also blue and marked "Win"?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{40}$"},{"key":"B","text":"$\\frac{8}{40}$"},{"key":"C","text":"$\\frac{8}{39}$"},{"key":"D","text":"$\\frac{9}{39}$"}]$lyceon_json$::jsonb, 'C', NULL, E'After drawing one blue "Win" card, there are $9 - 1 = 8$ blue "Win" cards remaining out of $40 - 1 = 39$ total cards remaining. The probability is $\\frac{8}{39}$. The distractor $\\frac{9}{40}$ ignores the without-replacement condition entirely, using the original counts. The distractor $\\frac{8}{40}$ correctly reduces the numerator by $1$ for the removed card but fails to reduce the denominator, treating the draw as if the total pool did not shrink. The distractor $\\frac{9}{39}$ reduces only the denominator but not the numerator, as if the removed card was not from the blue "Win" category.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21KXVSH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A data set contains the values 22, 27, 31, 31, 35, 38, and 42. What is the interquartile range of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'The data in order is 22, 27, 31, 31, 35, 38, 42. The median (4th value) is 31. The lower half consists of 22, 27, 31, so the first quartile Q1 is 27. The upper half consists of 35, 38, 42, so the third quartile Q3 is 38. The interquartile range is Q3 − Q1 = 38 − 27 = 11. A common error is computing the full range (42 − 22 = 20) instead of the interquartile range. Another error is including the median in both halves, which changes the quartile values.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM224Q711', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A university researcher found that students who attended optional review sessions scored higher on final exams than students who did not attend. No random assignment was used; students chose whether to attend. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Attending review sessions causes higher exam scores."},{"key":"B","text":"There is an association between attending review sessions and higher exam scores."},{"key":"C","text":"Students who do not attend review sessions are less intelligent."},{"key":"D","text":"The study proves that review sessions are ineffective for students who choose not to attend."}]$lyceon_json$::jsonb, 'B', NULL, E'Because students self-selected into attending or not attending review sessions (no random assignment), this is an observational study. Observational studies can establish associations but cannot establish causation, since confounding variables (such as motivation or study habits) may explain the difference in scores. The option claiming attendance causes higher scores inappropriately draws a causal conclusion from an observational study. The option about intelligence makes an unsupported claim about a variable not measured in the study. The option about ineffectiveness reverses the observed finding and draws a conclusion not supported by the data.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23FT4XW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A data set contains the values 14, 17, 17, 19, and 23. What is the mean of this data set?', NULL, $lyceon_json$[{"key":"A","text":"17"},{"key":"B","text":"18"},{"key":"C","text":"19"},{"key":"D","text":"23"}]$lyceon_json$::jsonb, 'B', NULL, E'The mean is (14 + 17 + 17 + 19 + 23) ÷ 5 = 90 ÷ 5 = 18. The value 17 is the median (and mode) of the data set, not the mean. The value 19 results from a summation error such as computing the total as 95 instead of 90. The value 23 is the maximum value, which would result from misreading the question as asking for the range or the largest value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23GU667', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'A plumber charges a $63 service fee plus $37 per hour for labor. A second plumber charges no service fee but $52 per hour. For how many hours of labor will both plumbers charge the same total amount?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{63}{89}$"},{"key":"B","text":"$\\frac{63}{15}$"},{"key":"C","text":"$\\frac{37}{52}$"},{"key":"D","text":"$\\frac{63}{52}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set the two costs equal: $63 + 37h = 52h$. Subtract $37h$ from both sides: $63 = 15h$. Divide by $15$: $h = \\frac{63}{15} = \\frac{21}{5}$. The value $\\frac{63}{89}$ comes from incorrectly adding the hourly rates ($37 + 52 = 89$) and dividing $63$ by the sum, an equation setup error. The value $\\frac{37}{52}$ comes from forming the ratio of the two hourly rates without incorporating the service fee, reflecting a concept gap. The value $\\frac{63}{52}$ comes from dividing the service fee by only the second plumber''s rate, ignoring the subtraction of the first plumber''s hourly rate (partial reasoning).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23NJSUD', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two straight lines intersect at a point. If one of the four angles formed measures $53°$, what is the measure of the angle adjacent to it?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$53°$"},{"key":"C","text":"$106°$"},{"key":"D","text":"$127°$"}]$lyceon_json$::jsonb, 'D', NULL, E'When two lines intersect, adjacent angles are supplementary (sum to $180°$). The adjacent angle is $180° - 53° = 127°$. The distractor $37°$ results from finding the complement ($90° - 53°$) instead of the supplement, confusing complementary and supplementary angles. The distractor $53°$ mistakes the adjacent angle for the vertical angle, which would be equal to the original. The distractor $106°$ comes from doubling $53°$, an arithmetic error with no geometric basis.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM23WCJ5R', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'mcq', E'A rectangular prism has dimensions $7$ cm, $11$ cm, and $4$ cm. What is the total surface area of the prism?', NULL, $lyceon_json$[{"key":"A","text":"$149$ cm$^2$"},{"key":"B","text":"$298$ cm$^2$"},{"key":"C","text":"$308$ cm$^2$"},{"key":"D","text":"$596$ cm$^2$"}]$lyceon_json$::jsonb, 'B', NULL, E'The surface area of a rectangular prism is $SA = 2(lw + lh + wh)$. Substituting: $SA = 2(7 \\times 11 + 7 \\times 4 + 11 \\times 4) = 2(77 + 28 + 44) = 2(149) = 298$ cm$^2$. The distractor $149$ cm$^2$ computes only half the surface area by omitting the factor of $2$, finding only the three distinct face areas without accounting for each pair. The distractor $308$ cm$^2$ computes the volume ($7 \\times 11 \\times 4 = 308$) instead of the surface area, confusing the two formulas. The distractor $596$ cm$^2$ incorrectly multiplies by $4$ instead of $2$, doubling the correct answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM249D3LO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $13$ tiles numbered $1$ through $13$. One tile is drawn at random. What is the probability that the tile shows a prime number?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{13}$"},{"key":"B","text":"$\\frac{6}{13}$"},{"key":"C","text":"$\\frac{7}{13}$"},{"key":"D","text":"$\\frac{4}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The prime numbers from $1$ through $13$ are $2, 3, 5, 7, 11,$ and $13$, giving $6$ primes out of $13$ total tiles. The probability is $\\frac{6}{13}$. The distractor $\\frac{5}{13}$ results from forgetting that $13$ itself is prime. The distractor $\\frac{7}{13}$ results from incorrectly counting $1$ as a prime number. The distractor $\\frac{4}{13}$ results from only counting single-digit primes ($2, 3, 5, 7$) and missing $11$ and $13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM251VPRG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A health magazine reported that people who eat breakfast daily have a $23\\%$ lower risk of developing heart disease than those who skip breakfast. The data came from a $14$-year observational study tracking the dietary habits and health outcomes of $29{,}000$ male health professionals. A reader concludes: "Eating breakfast prevents heart disease." Which of the following is the strongest reason this conclusion is not justified?', NULL, $lyceon_json$[{"key":"A","text":"The study only tracked male health professionals, so the results may not generalize to the broader population."},{"key":"B","text":"Fourteen years is not long enough to study heart disease outcomes."},{"key":"C","text":"Because the study is observational, confounding variables such as overall lifestyle habits could explain the association, and causation cannot be established."},{"key":"D","text":"A $23\\%$ reduction is too small to be meaningful."}]$lyceon_json$::jsonb, 'C', NULL, E'The strongest reason the causal conclusion is unjustified is that the study is observational: participants were not randomly assigned to eat or skip breakfast, so systematic differences between the groups (such as exercise habits, income, smoking status, or overall health consciousness) may confound the relationship. Without random assignment, the observed association cannot establish that eating breakfast itself causes reduced heart disease risk. The option about generalizability identifies a real limitation (external validity), but it does not address the fundamental issue of whether the relationship is causal. The option about $14$ years being insufficient is unfounded — $14$ years is a substantial follow-up period for cardiovascular outcomes. The option dismissing a $23\\%$ reduction as too small confuses effect size with statistical and clinical significance; a $23\\%$ risk reduction is clinically meaningful if real.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25VDDS7', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is the completely factored form of $6x^3 - 15x^2 + 9x$?', NULL, $lyceon_json$[{"key":"A","text":"$3x(2x - 3)(x - 1)$"},{"key":"B","text":"$3x(2x + 3)(x - 1)$"},{"key":"C","text":"$3(2x^2 - 5x + 3)$"},{"key":"D","text":"$3x(2x - 1)(x - 3)$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, factor out the greatest common factor $3x$: $6x^3 - 15x^2 + 9x = 3x(2x^2 - 5x + 3)$. Then factor the quadratic $2x^2 - 5x + 3$. We need two numbers that multiply to $2 \\times 3 = 6$ and add to $-5$; those are $-2$ and $-3$, giving $2x^2 - 2x - 3x + 3 = 2x(x - 1) - 3(x - 1) = (2x - 3)(x - 1)$. The complete factorization is $3x(2x - 3)(x - 1)$. The distractor $3x(2x + 3)(x - 1)$ introduces a sign error in the first binomial factor, producing $3x(2x^2 + x - 3) = 6x^3 + 3x^2 - 9x$, which does not match. The distractor $3(2x^2 - 5x + 3)$ fails to factor out $x$ from the GCF and does not complete the factorization of the quadratic. The distractor $3x(2x - 1)(x - 3)$ expands to $3x(2x^2 - 7x + 3) = 6x^3 - 21x^2 + 9x$, reflecting an incorrect factoring of the inner quadratic.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26IFXON', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $7x + 4y = 29$. Line $q$ is perpendicular to line $p$ and passes through the point $(-2, 9)$. What is the equation of line $q$?', NULL, $lyceon_json$[{"key":"A","text":"$y = \\frac{4}{7}x + \\frac{71}{7}$"},{"key":"B","text":"$y = -\\frac{7}{4}x + \\frac{11}{2}$"},{"key":"C","text":"$y = -\\frac{4}{7}x + \\frac{55}{7}$"},{"key":"D","text":"$y = \\frac{7}{4}x + \\frac{25}{2}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite line $p$ in slope-intercept form: $4y = -7x + 29$, so $y = -\\frac{7}{4}x + \\frac{29}{4}$. The slope of $p$ is $-\\frac{7}{4}$. A perpendicular line has slope equal to the negative reciprocal: $\\frac{4}{7}$. Using point $(-2, 9)$: $y - 9 = \\frac{4}{7}(x + 2)$, so $y = \\frac{4}{7}x + \\frac{8}{7} + 9 = \\frac{4}{7}x + \\frac{71}{7}$. The equation $y = -\\frac{7}{4}x + \\frac{11}{2}$ uses the slope of line $p$ itself instead of the perpendicular slope (concept gap — not taking the negative reciprocal). The equation $y = -\\frac{4}{7}x + \\frac{55}{7}$ takes the reciprocal but not the negative, yielding a wrong sign. The equation $y = \\frac{7}{4}x + \\frac{25}{2}$ negates the slope of $p$ without taking the reciprocal (partial reasoning).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27D42BU', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'If $f(x) = 2x^2 + 5x - 3$, what is the value of $f(-3)$?', NULL, $lyceon_json$[{"key":"A","text":"$-24$"},{"key":"B","text":"$0$"},{"key":"C","text":"$6$"},{"key":"D","text":"$30$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substitute $x = -3$ into the function: $f(-3) = 2(-3)^2 + 5(-3) - 3 = 2(9) - 15 - 3 = 18 - 15 - 3 = 0$. The distractor $-24$ results from failing to square $-3$ and instead computing $2(-3) + 5(-3) - 3 = -6 - 15 - 3 = -24$. The distractor $6$ results from a sign error on the constant term, computing $18 - 15 + 3 = 6$ instead of $18 - 15 - 3$. The distractor $30$ results from evaluating $f(3)$ instead of $f(-3)$: $2(9) + 15 - 3 = 30$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AMV2AH', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A carpenter has $\\$340$ to spend on wood planks and nails. Each wood plank costs $\\$17$ and each box of nails costs $\\$8$. If $p$ represents the number of planks and $n$ represents the number of boxes of nails, which inequality represents all possible combinations the carpenter can purchase?', NULL, $lyceon_json$[{"key":"A","text":"$17p + 8n \\leq 340$"},{"key":"B","text":"$8p + 17n \\leq 340$"},{"key":"C","text":"$17p + 8n \\geq 340$"},{"key":"D","text":"$17p + 8n < 340$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total cost is $17$ per plank times $p$ planks plus $8$ per box times $n$ boxes, and this total must not exceed $\\$340$. This gives $17p + 8n \\leq 340$. The distractor $8p + 17n \\leq 340$ reverses which coefficient goes with which variable, a setup error from mismatching costs to items. The distractor $17p + 8n \\geq 340$ uses the wrong direction for the inequality, implying the carpenter must spend at least $\\$340$ rather than at most. The distractor $17p + 8n < 340$ uses a strict inequality, which would exclude spending exactly $\\$340$; since the carpenter can spend up to and including the full budget, the non-strict inequality $\\leq$ is correct.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D11MMB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $8x - 5y = 35$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$\\frac{35}{8}$"},{"key":"D","text":"$-\\frac{35}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set $x = 0$: $8(0) - 5y = 35$, so $-5y = 35$, giving $y = -7$. The value $7$ results from dividing $35$ by $5$ but dropping the negative sign (sign error). The value $\\frac{35}{8}$ results from setting $y = 0$ and solving for $x$ instead of finding the $y$-intercept (concept gap — confusing $x$-intercept with $y$-intercept). The value $-\\frac{35}{8}$ results from the same $x$-intercept confusion but keeping an incorrect negative (partial reasoning).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DMB44S', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'The equation $kx^2 + 8x + 2 = 0$, where $k$ is a positive constant, has exactly one real solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$2$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'C', NULL, E'A quadratic equation has exactly one real solution when its discriminant equals zero. For $kx^2 + 8x + 2 = 0$, the discriminant is $b^2 - 4ac = 64 - 4(k)(2) = 64 - 8k$. Setting $64 - 8k = 0$ gives $k = 8$. The distractor $k = 2$ comes from using $b = 8$ directly (without squaring) in a partial setup such as $8 = 4k$, yielding $k = 2$. The distractor $k = 4$ results from computing $64 - 4(k)(2) = 0$ but incorrectly simplifying as $64 = 16k$ (using $4 \\cdot 4 = 16$ instead of $4 \\cdot 2 = 8$), giving $k = 4$. The distractor $k = 16$ comes from computing $b^2 / 4 = 64 / 4 = 16$, omitting the factor of $c = 2$ in the denominator.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E7JHEH', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'If $7x - 4 < 31$, which of the following is a possible value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'A', NULL, E'Solving $7x - 4 < 31$: add $4$ to both sides to get $7x < 35$, then divide by $7$ to get $x < 5$. The value $3$ is less than $5$, so it satisfies the inequality. The value $5$ does not satisfy the strict inequality since $7(5) - 4 = 31$, which is not less than $31$. The value $7$ gives $7(7) - 4 = 45$, which exceeds $31$; a student might pick this after incorrectly dividing $31$ by $4$ or miscalculating the boundary. The value $9$ gives $7(9) - 4 = 59$, which far exceeds $31$; a student might pick this after a sign error that reverses the inequality direction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EBWQMX', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'A $23$-foot ladder leans against a vertical wall, making an angle of $71°$ with the horizontal ground. How high up the wall does the ladder reach? Round your answer to the nearest tenth of a foot.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21.7', ARRAY['21.7'], E'The ladder, the wall, and the ground form a right triangle. The ladder is the hypotenuse ($23$ ft), the angle with the ground is $71°$, and the height up the wall is the side opposite this angle. Using $\\sin(71°) = \\frac{\\text{height}}{23}$, we get height $= 23 \\sin(71°) \\approx 23 \\times 0.9455 \\approx 21.7$ feet. A common error is using cosine instead of sine, which gives the horizontal distance from the wall ($23 \\cos(71°) \\approx 7.5$). Another error is using tangent, which would require the adjacent side rather than the hypotenuse.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FEYPKL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $26$ centimeters. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$13\\pi$ cm"},{"key":"B","text":"$26\\pi$ cm"},{"key":"C","text":"$169\\pi$ cm"},{"key":"D","text":"$52\\pi$ cm"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 26$ gives $C = 26\\pi$ cm. The distractor $13\\pi$ uses the radius ($26 / 2 = 13$) in the formula $C = \\pi r$ instead of $C = 2\\pi r$ or $C = \\pi d$. The distractor $169\\pi$ computes the area formula $\\pi r^2 = \\pi(13)^2 = 169\\pi$ instead of the circumference. The distractor $52\\pi$ doubles the correct circumference, as if the formula were $C = 2\\pi d$ rather than $C = \\pi d$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FZT7YC', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of $x$ in the solution to the system of equations below?$$\\begin{cases} x + y = 19 \\\\ x - y = 3 \\end{cases}$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Adding the two equations eliminates $y$: $(x + y) + (x - y) = 19 + 3$, which simplifies to $2x = 22$, so $x = 11$. Substituting back: $11 + y = 19$ gives $y = 8$, and checking the second equation: $11 - 8 = 3$, which confirms the solution.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5C4MV', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(7, -3)$ and $(11, 13)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-31', ARRAY['-31'], E'First find the slope: $m = \\frac{13 - (-3)}{11 - 7} = \\frac{16}{4} = 4$. Use point-slope form with $(7, -3)$: $y - (-3) = 4(x - 7)$, which simplifies to $y + 3 = 4x - 28$, so $y = 4x - 31$. The $y$-intercept is $-31$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GARTJ8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In right triangle $DEF$ with the right angle at $F$, $DE = 13$ and $DF = 9$. What is $\\cos(D)$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{13}$"},{"key":"B","text":"$\\frac{2\\sqrt{22}}{13}$"},{"key":"C","text":"$\\frac{9}{2\\sqrt{22}}$"},{"key":"D","text":"$\\frac{13}{9}$"}]$lyceon_json$::jsonb, 'A', NULL, E'In right triangle $DEF$ with the right angle at $F$, the hypotenuse is $DE = 13$ and the side adjacent to angle $D$ is $DF = 9$. By definition, $\\cos(D) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{9}{13}$. The distractor $\\frac{2\\sqrt{22}}{13}$ computes $\\sin(D)$ instead, using the opposite side $EF = \\sqrt{13^2 - 9^2} = \\sqrt{88} = 2\\sqrt{22}$ over the hypotenuse. The distractor $\\frac{9}{2\\sqrt{22}}$ incorrectly uses the opposite side as the denominator, computing adjacent over opposite. The distractor $\\frac{13}{9}$ inverts the cosine ratio, computing hypotenuse over adjacent.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GB6GHW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'What is the minimum value of the function $p(x) = 5x^2 + 30x + 49$?', NULL, $lyceon_json$[{"key":"A","text":"$4$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$49$"},{"key":"D","text":"$94$"}]$lyceon_json$::jsonb, 'A', NULL, E'Complete the square: $p(x) = 5(x^2 + 6x) + 49 = 5(x^2 + 6x + 9 - 9) + 49 = 5(x + 3)^2 - 45 + 49 = 5(x + 3)^2 + 4$. Since $5(x + 3)^2 \\geq 0$ for all real $x$, the minimum value of $p(x)$ is $4$, occurring at $x = -3$. The distractor $-3$ gives the $x$-coordinate of the vertex rather than the minimum value of the function. The distractor $49$ assumes the minimum value equals the constant term of the original expression, ignoring the effect of the linear and quadratic terms. The distractor $94$ results from a sign error when completing the square, computing $+45 + 49 = 94$ instead of $-45 + 49 = 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HGADIP', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $(9x^4)(3x^3)$?', NULL, $lyceon_json$[{"key":"A","text":"$27x^{12}$"},{"key":"B","text":"$27x^7$"},{"key":"C","text":"$12x^7$"},{"key":"D","text":"$12x^{12}$"}]$lyceon_json$::jsonb, 'B', NULL, E'When multiplying monomials, multiply the coefficients and add the exponents of like bases. The coefficients are $9 \\times 3 = 27$, and the exponents are $4 + 3 = 7$, giving $27x^7$. The distractor $27x^{12}$ results from multiplying the exponents ($4 \\times 3 = 12$) instead of adding them. The distractor $12x^7$ results from adding the coefficients ($9 + 3 = 12$) instead of multiplying them. The distractor $12x^{12}$ combines both errors: adding the coefficients and multiplying the exponents.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HTBPSQ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 11x - 23$. What is the value of $f(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$54$"},{"key":"B","text":"$100$"},{"key":"C","text":"$46$"},{"key":"D","text":"$-100$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substitute $x = 7$: $f(7) = 11(7) - 23 = 77 - 23 = 54$. The value $100$ results from adding $23$ instead of subtracting (sign error): $77 + 23 = 100$. The value $46$ results from computing $11 \\times 7 = 69$ incorrectly (arithmetic slip in the multiplication) and then subtracting $23$. The value $-100$ results from reversing the computation as $23 - 77$ and then doubling or misapplying the sign, reflecting a concept gap in function evaluation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HWJDSB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A retailer purchases a jacket for \\$225 and marks up the price by 40%. The retailer then applies a store-wide discount to the marked-up price. After the discount, the retailer''s profit on the jacket is 12% of the purchase price. What is the discount percentage applied to the marked-up price?', NULL, $lyceon_json$[{"key":"A","text":"12%"},{"key":"B","text":"15%"},{"key":"C","text":"20%"},{"key":"D","text":"28%"}]$lyceon_json$::jsonb, 'C', NULL, E'The marked-up price is 225 × 1.40 = 315 dollars. The profit is 12% of 225, which is 0.12 × 225 = 27 dollars. The selling price after discount is 225 + 27 = 252 dollars. The discount amount is 315 − 252 = 63 dollars. The discount percentage is (63 ÷ 315) × 100 = 20%. The value 12% results from confusing the discount percentage with the profit percentage. The value 15% arises from a computational error in the division step. The value 28% results from dividing the discount amount by the purchase price (63 ÷ 225 ≈ 28%) instead of by the marked-up price.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JIHFCG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'grid_in', E'A parallelogram has a base of $23$ cm and a height of $11$ cm. What is the area of the parallelogram, in square centimeters?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '253', ARRAY['253'], E'The area of a parallelogram is $A = bh$, where $b$ is the base and $h$ is the perpendicular height. Substituting gives $A = 23 \\times 11 = 253$ square centimeters. A common error is using the triangle formula $\\frac{1}{2}bh = 126.5$, which incorrectly halves the area. Another error is computing the perimeter ($2(23 + 11) = 68$) instead of the area.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KF2M9S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company tested a new headache medication by randomly assigning $260$ participants to either a treatment group (receiving the medication) or a control group (receiving a placebo). Neither the participants nor the researchers administering the pills knew which group each participant belonged to. At the end of the trial, the treatment group reported significantly fewer headaches. Which feature of this study design most directly supports a causal conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The large number of participants ($260$)"},{"key":"B","text":"The random assignment of participants to treatment and control groups"},{"key":"C","text":"The use of a placebo in the control group"},{"key":"D","text":"The double-blind design preventing participants and researchers from knowing group assignments"}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment is the feature that most directly supports a causal conclusion because it ensures that, on average, the treatment and control groups are comparable on all variables — both measured and unmeasured — so any observed difference can be attributed to the treatment itself. The large sample size increases statistical power but does not, by itself, allow causal inference. The placebo controls for the psychological effect of receiving treatment but does not balance confounding variables across groups. The double-blind design reduces bias in outcome measurement but, without random assignment, would not support a causal claim.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KTXRTJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A chemist mixes Solution A and Solution B in a ratio of 5 to 13. If the chemist needs to prepare 126 milliliters of the combined mixture, how many milliliters of Solution A are needed?', NULL, $lyceon_json$[{"key":"A","text":"30"},{"key":"B","text":"35"},{"key":"C","text":"70"},{"key":"D","text":"91"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of parts in the ratio is 5 + 13 = 18. Each part equals 126 ÷ 18 = 7 milliliters. Solution A accounts for 5 parts, so 5 × 7 = 35 milliliters are needed. The value 30 results from an incorrect setup such as dividing 126 by a wrong total of parts. The value 70 arises from doubling the correct answer, as if each part contributes 14 mL instead of 7 mL. The value 91 results from computing the amount of Solution B (13 × 7 = 91) instead of Solution A.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KVGF1L', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'What is the radius of the circle with equation $x^2 + y^2 - 14x + 6y + 33 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{33}$"},{"key":"B","text":"$5$"},{"key":"C","text":"$25$"},{"key":"D","text":"$\\sqrt{91}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Complete the square for both variables. Group: $(x^2 - 14x) + (y^2 + 6y) = -33$. Complete the square: $(x^2 - 14x + 49) + (y^2 + 6y + 9) = -33 + 49 + 9 = 25$. This gives $(x - 7)^2 + (y + 3)^2 = 25$, so $r^2 = 25$ and $r = 5$. The distractor $\\sqrt{33}$ mistakenly treats the constant term $33$ as $r^2$, ignoring the need to complete the square. The distractor $25$ identifies $r^2 = 25$ but reports $r^2$ as the radius instead of taking the square root. The distractor $\\sqrt{91}$ results from adding all terms on the right ($49 + 9 + 33 = 91$) instead of subtracting $33$, a sign error in rearranging the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NAUDAL', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A landscaping crew can spread 11 cubic yards of mulch in 3 hours. At this rate, how many cubic yards of mulch can the crew spread in 9 hours?', NULL, $lyceon_json$[{"key":"A","text":"27"},{"key":"B","text":"33"},{"key":"C","text":"36"},{"key":"D","text":"99"}]$lyceon_json$::jsonb, 'B', NULL, E'The crew spreads mulch at a rate of 11 cubic yards per 3 hours. Since 9 hours is 3 times 3 hours, the crew can spread 11 × 3 = 33 cubic yards. The value 27 results from computing 9 × 3 = 27, confusing the time values. The value 36 comes from incorrectly treating the rate as 4 cubic yards per hour (rounding 11/3) and computing 4 × 9. The value 99 results from multiplying 11 × 9 without accounting for the 3-hour base period.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NS0ZQC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $500$ voters in a city found that $58\\%$ support a proposed park renovation. The margin of error for this estimate is $\\pm 3.7\\%$. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"It is plausible that between $54.3\\%$ and $61.7\\%$ of all voters in the city support the park renovation."},{"key":"B","text":"Exactly $58\\%$ of all voters in the city support the park renovation."},{"key":"C","text":"Between $54.3\\%$ and $61.7\\%$ of the $500$ sampled voters support the park renovation."},{"key":"D","text":"If the survey were repeated, $58\\%$ of the new sample would support the park renovation."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error defines an interval around the sample statistic ($58\\% \\pm 3.7\\%$, or $54.3\\%$ to $61.7\\%$) within which the true population parameter plausibly falls. The option stating it is plausible that between $54.3\\%$ and $61.7\\%$ of all voters support the renovation correctly describes this. The option stating exactly $58\\%$ ignores sampling variability and treats the sample statistic as the exact population parameter. The option referring to the $500$ sampled voters applies the interval to the sample rather than the population, which misunderstands the purpose of the margin of error. The option about repeating the survey confuses the confidence interval with a prediction about future samples.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NXLAU5', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'$$\\begin{cases} 5x - 3y = 27 \\\\ 2x + 3y = 15 \\end{cases}$$What is the value of $y$ in the solution to the system of equations shown above?', NULL, $lyceon_json$[{"key":"A","text":"$-2$"},{"key":"B","text":"$1$"},{"key":"C","text":"$3$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations: $(5x - 3y) + (2x + 3y) = 27 + 15$ gives $7x = 42$, so $x = 6$. Substituting into the second equation: $2(6) + 3y = 15$ gives $12 + 3y = 15$, so $3y = 3$ and $y = 1$. The distractor $-2$ results from a sign error, such as computing $12 + 3y = 15$ as $3y = 15 - 12$ but then incorrectly applying a negative sign to get $y = -2$. The distractor $3$ comes from confusing the coefficient of $y$ with the value of $y$, or from solving $3y = 9$ after miscomputing $15 - 12$ as $9$. The distractor $6$ confuses the value of $x$ with the value of $y$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O21D3R', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'The list below shows the number of books read by 13 students during a semester.\\n2, 4, 5, 5, 7, 8, 9, 9, 11, 12, 14, 15, 19\\nThe student who read 19 books transfers to another school and is removed from the data set. Which of the following correctly describes the effect of this removal on the mean and median of the data set?', NULL, $lyceon_json$[{"key":"A","text":"The mean decreases and the median stays the same."},{"key":"B","text":"The mean decreases and the median decreases."},{"key":"C","text":"The mean stays the same and the median decreases."},{"key":"D","text":"Both the mean and the median stay the same."}]$lyceon_json$::jsonb, 'B', NULL, E'Original data (n = 13): sum is 2 + 4 + 5 + 5 + 7 + 8 + 9 + 9 + 11 + 12 + 14 + 15 + 19 = 120, so the mean is 120 ÷ 13 ≈ 9.23, and the median (7th value) is 9. After removing 19, the data set (n = 12) has sum 101, so the mean is 101 ÷ 12 ≈ 8.42 (decreased). The new median is the average of the 6th and 7th values: (8 + 9) ÷ 2 = 8.5 (decreased from 9). Both the mean and the median decrease. The option stating only the mean decreases while the median stays the same reflects a failure to recompute the median for an even-count data set. The option stating only the median decreases ignores the effect of removing a high value on the mean. The option stating both stay the same misunderstands how removing an extreme value affects central tendency.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O5Q35P', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'grid_in', E'A linear function $h$ satisfies $h(3) = 19$ and $h(14) = 74$. What is the rate of change of $h$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The rate of change (slope) is $\\frac{h(14) - h(3)}{14 - 3} = \\frac{74 - 19}{11} = \\frac{55}{11} = 5$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OA73A4', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $g(1) = 12$ and $g(4) = 324$, what is the value of $g(3)$?', NULL, $lyceon_json$[{"key":"A","text":"$36$"},{"key":"B","text":"$108$"},{"key":"C","text":"$144$"},{"key":"D","text":"$324$"}]$lyceon_json$::jsonb, 'B', NULL, E'From $g(1) = ab = 12$ and $g(4) = ab^4 = 324$, divide the second equation by the first: $\\frac{ab^4}{ab} = b^3 = \\frac{324}{12} = 27$, so $b = 3$. Then $a = \\frac{12}{3} = 4$. Therefore $g(3) = 4 \\cdot 3^3 = 4 \\cdot 27 = 108$. The distractor $36$ results from computing $g(2) = 4 \\cdot 3^2 = 36$ instead of $g(3)$, an off-by-one error in the exponent. The distractor $144$ results from an arithmetic slip where $3^3$ is miscalculated as $36$ instead of $27$, yielding $4 \\cdot 36 = 144$. The distractor $324$ simply restates the given value of $g(4)$, which would result from misreading the question and reporting a given value instead of computing the requested one.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONNP6M', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'What value of $x$ satisfies the equation $13x + 41 = 158$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Subtract $41$ from both sides to get $13x = 117$. Divide both sides by $13$ to find $x = 9$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OZ9QS6', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A delivery truck can carry at most $2{,}200$ pounds. Large crates weigh $130$ pounds each and small crates weigh $55$ pounds each. The truck already has $7$ large crates loaded. What is the maximum number of small crates that can still be added to the truck?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$22$"},{"key":"C","text":"$23$"},{"key":"D","text":"$24$"}]$lyceon_json$::jsonb, 'C', NULL, E'The $7$ large crates weigh $7 \\times 130 = 910$ pounds. The remaining capacity is $2{,}200 - 910 = 1{,}290$ pounds. Setting up the inequality $55s \\leq 1{,}290$ and dividing both sides by $55$ gives $s \\leq 23.\\overline{45}$. Since the number of crates must be a whole number, the maximum is $23$ (since $23 \\times 55 = 1{,}265 \\leq 1{,}290$ but $24 \\times 55 = 1{,}320 > 1{,}290$). The distractor $21$ results from an arithmetic error such as computing $7 \\times 130 = 1{,}050$ (adding an extra $140$) and then dividing $(2{,}200 - 1{,}050)/55 \\approx 20.9$, rounding to $21$. The distractor $22$ results from subtracting incorrectly, for example computing $2{,}200 - 910 = 1{,}210$ and then $1{,}210/55 = 22$. The distractor $24$ results from rounding $23.45$ up to $24$ instead of down, ignoring that partial crates cannot be loaded.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PPCM43', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'Which of the following is equivalent to $\\frac{27x^3 + 125}{3x + 5}$?', NULL, $lyceon_json$[{"key":"A","text":"$9x^2 + 15x + 25$"},{"key":"B","text":"$9x^2 + 30x + 25$"},{"key":"C","text":"$9x^2 - 15x + 25$"},{"key":"D","text":"$9x^2 - 15x - 25$"}]$lyceon_json$::jsonb, 'C', NULL, E'Recognize $27x^3 + 125$ as a sum of cubes: $(3x)^3 + 5^3$. The sum-of-cubes formula states $a^3 + b^3 = (a + b)(a^2 - ab + b^2)$. With $a = 3x$ and $b = 5$, we get $(3x + 5)(9x^2 - 15x + 25)$. Dividing by $(3x + 5)$ yields $9x^2 - 15x + 25$. The distractor $9x^2 + 15x + 25$ uses a positive middle term, which would correspond to misapplying the formula as $a^2 + ab + b^2$ (the factor from the difference-of-cubes identity). The distractor $9x^2 + 30x + 25$ results from squaring the binomial $(3x + 5)^2$ instead of applying the sum-of-cubes pattern. The distractor $9x^2 - 15x - 25$ incorrectly negates the constant term $b^2 = 25$, yielding $-25$ instead of $+25$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RM5BEI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ employees at a company found that $74$ drink coffee only, $53$ drink tea only, $31$ drink both coffee and tea, and the rest drink neither. If an employee is selected at random from those who drink coffee, what is the probability that the employee also drinks tea?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{31}{200}$"},{"key":"B","text":"$\\frac{31}{105}$"},{"key":"C","text":"$\\frac{31}{84}$"},{"key":"D","text":"$\\frac{31}{127}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of coffee drinkers includes those who drink coffee only ($74$) plus those who drink both ($31$), giving $74 + 31 = 105$. Of these, $31$ also drink tea. The conditional probability is $\\frac{31}{105}$. The distractor $\\frac{31}{200}$ divides by the total number of employees instead of conditioning on coffee drinkers. The distractor $\\frac{31}{84}$ incorrectly uses $53 + 31 = 84$ (the tea drinkers) as the denominator. The distractor $\\frac{31}{127}$ uses $74 + 53 = 127$, adding the two "only" groups instead of finding total coffee drinkers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RXWLWQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A car traveling at a constant speed covers 247 kilometers in 3 hours and 15 minutes. A second car, also traveling at a constant speed, covers 194 kilometers in 2 hours and 30 minutes. To the nearest kilometer per hour, how much faster is the second car traveling than the first car?', NULL, $lyceon_json$[{"key":"A","text":"1"},{"key":"B","text":"2"},{"key":"C","text":"6"},{"key":"D","text":"21"}]$lyceon_json$::jsonb, 'B', NULL, E'The first car travels 247 km in 3 hours 15 minutes, which is 3.25 hours, so its speed is 247 ÷ 3.25 = 76 km/h. The second car travels 194 km in 2 hours 30 minutes, which is 2.5 hours, so its speed is 194 ÷ 2.5 = 77.6 km/h. The difference is 77.6 − 76 = 1.6 km/h, which rounds to 2 km/h. The value 1 results from truncating 1.6 rather than rounding. The value 6 arises from converting minutes incorrectly (e.g., treating 3 hours 15 minutes as 3.15 hours), which inflates the speed gap. The value 21 results from subtracting distances (247 − 194 = 53) and dividing by an incorrect time difference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"unit_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SIX5BS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, $\\angle P = 41°$ and $\\angle Q = 67°$. Point $S$ lies on $\\overline{PQ}$ such that $\\overline{RS}$ bisects $\\angle R$. What is the measure of $\\angle RSQ$?', NULL, $lyceon_json$[{"key":"A","text":"$36°$"},{"key":"B","text":"$72°$"},{"key":"C","text":"$77°$"},{"key":"D","text":"$108°$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, $\\angle R = 180° - 41° - 67° = 72°$. Since $\\overline{RS}$ bisects $\\angle R$, the angle $\\angle SRQ = 36°$. In triangle $RSQ$, the angle sum gives $\\angle RSQ = 180° - 67° - 36° = 77°$. The distractor $36°$ stops at finding half of $\\angle R$ without completing the triangle angle sum. The distractor $72°$ finds $\\angle R$ but fails to apply the bisector. The distractor $108°$ computes $180° - 72°$ as though $\\angle R$ and $\\angle RSQ$ were supplementary, which is incorrect since they are not on a straight line.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TSR2VH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A bookstore increases the price of a novel by 18%, bringing the new price to \\$41.30. What was the original price, in dollars, of the novel?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '35', ARRAY['35'], E'Let the original price be p. After an 18% increase, the new price is 1.18p = 41.30. Solving gives p = 41.30 ÷ 1.18 = 35. The original price was $35. A common error is computing 18% of 41.30 (which is 7.434) and subtracting to get approximately 33.87, but this incorrectly applies 18% to the new price rather than to the original price.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TTUX23', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the number of hours students study per week, \\(x\\), and their exam scores, \\(y\\). The line of best fit is \\(y = 4.7x + 29\\). One student studied 11 hours and scored 83. Another student studied 6 hours and scored 58. Which student''s actual exam score is farther from the value predicted by the line of best fit, and what is the absolute difference between that student''s actual score and predicted score?', NULL, $lyceon_json$[{"key":"A","text":"The student who studied 6 hours, by 0.8 points"},{"key":"B","text":"The student who studied 11 hours, by 1.5 points"},{"key":"C","text":"The student who studied 11 hours, by 2.3 points"},{"key":"D","text":"The student who studied 6 hours, by 2.3 points"}]$lyceon_json$::jsonb, 'C', NULL, E'For the student who studied 11 hours, the predicted score is 4.7(11) + 29 = 51.7 + 29 = 80.7. The absolute difference from the actual score of 83 is |83 − 80.7| = 2.3. For the student who studied 6 hours, the predicted score is 4.7(6) + 29 = 28.2 + 29 = 57.2. The absolute difference from the actual score of 58 is |58 − 57.2| = 0.8. The student who studied 11 hours has the larger residual at 2.3 points. The option stating 0.8 points for the 6-hour student gives the correct residual for that student but selects the wrong one as farther. The option stating 1.5 points results from subtracting the two residuals (2.3 − 0.8) rather than reporting the larger residual. The option assigning 2.3 to the 6-hour student assigns the correct magnitude to the wrong student.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U5K692', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of registered voters in a county and reports that $47\\%$ favor Candidate X, with a $95\\%$ confidence interval of $43\\%$ to $51\\%$. A local newspaper writes: "There is a $95\\%$ probability that between $43\\%$ and $51\\%$ of all registered voters in the county favor Candidate X." Which of the following best describes the accuracy of the newspaper''s statement?', NULL, $lyceon_json$[{"key":"A","text":"The statement is correct because the confidence interval gives the range of plausible values for the population proportion."},{"key":"B","text":"The statement is incorrect because the $95\\%$ refers to the method: in repeated sampling, about $95\\%$ of similarly constructed intervals would contain the true proportion, not that there is a $95\\%$ probability the true proportion is in this particular interval."},{"key":"C","text":"The statement is incorrect because the confidence interval applies only to the $47\\%$ sample proportion, not to the population."},{"key":"D","text":"The statement is correct because $47\\%$ is within the interval, confirming the population proportion is also in the interval."}]$lyceon_json$::jsonb, 'B', NULL, E'A $95\\%$ confidence level means that the procedure used to construct the interval will capture the true population parameter approximately $95\\%$ of the time across many repeated samples. Once a specific interval ($43\\%$ to $51\\%$) is computed, the true proportion either is or is not in that interval — it is not meaningful to assign a $95\\%$ probability to this fixed interval containing the parameter. The option calling the statement correct because the interval gives plausible values conflates the practical interpretation with the precise probabilistic meaning. The option stating the interval applies only to the sample proportion mischaracterizes confidence intervals, which are designed to estimate the population parameter. The option about $47\\%$ being within the interval confuses the sample statistic (which is always in the center of the interval) with evidence about the population parameter.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UV4PPP', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'If $\\frac{3(2x - 7)}{4} = 15$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{17}{2}$"},{"key":"B","text":"$\\frac{27}{2}$"},{"key":"C","text":"$\\frac{67}{6}$"},{"key":"D","text":"$\\frac{41}{6}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiply both sides by $4$ to get $3(2x - 7) = 60$. Distribute: $6x - 21 = 60$. Add $21$ to both sides: $6x = 81$. Divide by $6$: $x = \\frac{81}{6} = \\frac{27}{2}$. The value $\\frac{17}{2}$ results from subtracting $21$ instead of adding it (sign error). The value $\\frac{67}{6}$ results from dividing $60$ by $3$ first to get $20$ and then solving $2x - 7 = 20$ incorrectly as $2x = 20$ (forgetting to add $7$), yielding $\\frac{20}{2} + \\frac{7}{6}$ via a setup error. The value $\\frac{41}{6}$ results from failing to multiply the right side by $4$ and solving $3(2x - 7) = 15$ directly, getting $6x = 36 + 5 = 41$ through an arithmetic slip.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WVQQKV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A student scored 43 out of 50 on a quiz. What percent of the total points did the student score?', NULL, $lyceon_json$[{"key":"A","text":"43%"},{"key":"B","text":"84%"},{"key":"C","text":"86%"},{"key":"D","text":"93%"}]$lyceon_json$::jsonb, 'C', NULL, E'The percentage is (43 ÷ 50) × 100 = 86%. The value 43% results from treating the raw score as the percentage without dividing by the total. The value 84% comes from a computational slip such as using 42 instead of 43 in the numerator. The value 93% results from computing 100 − 7 = 93, incorrectly applying the complement of the missed points as if 7 points missed equals 93%.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y2NVUP', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'For what value of the constant $k$ does the system of equations below have no solution?$$\\begin{cases} 6x - 9y = 14 \\\\ 4x - ky = 7 \\end{cases}$$', NULL, $lyceon_json$[{"key":"A","text":"$-6$"},{"key":"B","text":"$-3$"},{"key":"C","text":"$3$"},{"key":"D","text":"$6$"}]$lyceon_json$::jsonb, 'D', NULL, E'A system of two linear equations has no solution when the lines are parallel, meaning they have equal slopes but different $y$-intercepts. For parallel lines, the ratios of corresponding coefficients of $x$ and $y$ must be equal while the ratio of constants differs: $\\frac{6}{4} = \\frac{9}{k}$ (using absolute coefficients from $6x - 9y$ and $4x - ky$). Cross-multiplying gives $6k = 36$, so $k = 6$. We verify the system has no solution: with $k = 6$, the equations become $6x - 9y = 14$ and $4x - 6y = 7$. Multiplying the second by $\\frac{3}{2}$ gives $6x - 9y = 10.5$, which contradicts $6x - 9y = 14$, confirming no solution. The distractor $-6$ results from introducing an erroneous negative sign during cross-multiplication. The distractor $-3$ arises from incorrectly using the ratio of constants ($\\frac{14}{7} = 2$) and computing $k = -9/2 \\cdot$ something, or from setting $\\frac{-9}{-k} = \\frac{14}{7}$ and solving incorrectly. The distractor $3$ arises from confusing the coefficient relationship, such as computing $\\frac{9}{6} = \\frac{k}{4}$ and incorrectly solving to get $k = 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YD5WTF', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'What are all the solutions to $\\sqrt{3x + 13} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -3$ only"},{"key":"B","text":"$x = 7$"},{"key":"C","text":"$x = -3$ and $x = 4$"},{"key":"D","text":"$x = 4$ only"}]$lyceon_json$::jsonb, 'D', NULL, E'Square both sides: $3x + 13 = (x + 1)^2 = x^2 + 2x + 1$. Rearranging gives $x^2 - x - 12 = 0$, which factors as $(x - 4)(x + 3) = 0$, yielding $x = 4$ or $x = -3$. Check $x = 4$: $\\sqrt{12 + 13} = \\sqrt{25} = 5$ and $4 + 1 = 5$; this is valid. Check $x = -3$: $\\sqrt{-9 + 13} = \\sqrt{4} = 2$ and $-3 + 1 = -2$; since $2 \\neq -2$, this is extraneous. Only $x = 4$ is a valid solution. The distractor $x = -3$ only selects the extraneous solution, failing to verify it in the original equation. The distractor $x = 7$ results from an arithmetic slip when solving the quadratic (e.g., incorrectly factoring $x^2 - x - 12$). The distractor listing both $x = -3$ and $x = 4$ fails to check for extraneous solutions introduced by squaring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YV4XIB', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'Lines $m$ and $n$ are parallel and are cut by a transversal $t$. The transversal makes an angle of $(4x + 11)°$ with line $m$ and a co-interior (same-side interior) angle of $(6x - 1)°$ with line $n$. What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17', ARRAY['17'], E'Co-interior angles (also called consecutive interior angles or same-side interior angles) formed by a transversal cutting parallel lines are supplementary. Therefore $(4x + 11) + (6x - 1) = 180$. Simplifying: $10x + 10 = 180$, so $10x = 170$, giving $x = 17$. A common error is setting the angles equal (as if they were alternate interior angles), which gives $6x - 1 = 4x + 11$, yielding $x = 6$. Another error is subtracting the expressions from $180$ separately and equating, leading to an incorrect setup.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z2UYNY', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'The legs of a right triangle are in the ratio $2{:}5$. If the hypotenuse of the triangle is $\\sqrt{203}$, what is the area of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$5\\sqrt{7}$"},{"key":"B","text":"$35$"},{"key":"C","text":"$7\\sqrt{29}$"},{"key":"D","text":"$70$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let the legs be $2k$ and $5k$. The hypotenuse is $\\sqrt{(2k)^2 + (5k)^2} = \\sqrt{4k^2 + 25k^2} = k\\sqrt{29}$. Setting $k\\sqrt{29} = \\sqrt{203}$ gives $k^2 \\cdot 29 = 203$, so $k^2 = 7$ and $k = \\sqrt{7}$. The legs are $2\\sqrt{7}$ and $5\\sqrt{7}$, and the area is $\\frac{1}{2}(2\\sqrt{7})(5\\sqrt{7}) = \\frac{1}{2}(10)(7) = 35$. The distractor $5\\sqrt{7}$ is merely the length of the longer leg, stopping before computing the area. The distractor $7\\sqrt{29}$ equals $k^2 \\cdot \\sqrt{29} = \\sqrt{203} \\cdot \\sqrt{7}$, confusing the hypotenuse expression with the area. The distractor $70$ omits the $\\frac{1}{2}$ factor in the triangle area formula, computing $10 \\times 7$ instead.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z4J4RE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher models the relationship between the number of hours of sunlight per day, \\(x\\), and the height in centimeters of a plant after 30 days, \\(y\\), with the equation \\(y = 1.7x + 8.3\\). Which of the following is the best interpretation of 1.7 in this context?', NULL, $lyceon_json$[{"key":"A","text":"For each additional hour of sunlight per day, the predicted plant height after 30 days increases by 1.7 centimeters."},{"key":"B","text":"For each additional centimeter of plant height, the number of sunlight hours per day increases by 1.7."},{"key":"C","text":"A plant that receives no sunlight is predicted to have a height of 1.7 centimeters after 30 days."},{"key":"D","text":"The plant grows at a rate of 8.3 centimeters per hour of sunlight per day."}]$lyceon_json$::jsonb, 'A', NULL, E'In the equation y = 1.7x + 8.3, the coefficient 1.7 is the slope, which represents the predicted change in y for each unit increase in x. Therefore, for each additional hour of sunlight per day, the predicted plant height increases by 1.7 centimeters. The option reversing the variables (centimeters per hour) misreads the direction of the relationship. The option stating 1.7 cm with no sunlight confuses the slope with the y-intercept (8.3). The option citing 8.3 as the rate swaps the slope and intercept values.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z87NF5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'If $4x^2 = 324$, what is the positive value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '9', ARRAY['9'], E'Divide both sides by 4 to get $x^2 = 81$. Taking the square root of both sides gives $x = \\pm 9$. Since the question asks for the positive value, $x = 9$. A common error is to take the square root of 324 directly without first dividing by 4, which would give $\\sqrt{324} = 18$. Another error is to divide 324 by 2 instead of 4, obtaining $x^2 = 162$ and an irrational result.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZN0S79', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The linear function $g$ is defined for all real numbers. The table below shows selected values of $g$.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZUV3G2', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A grain silo consists of a cylinder with radius $8$ feet and height $23$ feet, topped with a hemisphere of the same radius. What is the total volume of the silo?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5440\\pi}{3}$ ft$^3$"},{"key":"B","text":"$\\frac{6464\\pi}{3}$ ft$^3$"},{"key":"C","text":"$1472\\pi$ ft$^3$"},{"key":"D","text":"$\\frac{4928\\pi}{3}$ ft$^3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The cylinder volume is $\\pi r^2 h = \\pi(64)(23) = 1472\\pi$ ft$^3$. The hemisphere volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(512) = \\frac{1024\\pi}{3}$ ft$^3$. The total is $1472\\pi + \\frac{1024\\pi}{3} = \\frac{4416\\pi}{3} + \\frac{1024\\pi}{3} = \\frac{5440\\pi}{3}$ ft$^3$. The distractor $\\frac{6464\\pi}{3}$ uses the full sphere formula $\\frac{4}{3}\\pi r^3 = \\frac{2048\\pi}{3}$ instead of the hemisphere formula, giving $1472\\pi + \\frac{2048\\pi}{3} = \\frac{6464\\pi}{3}$. The distractor $1472\\pi$ computes only the cylinder volume and omits the hemisphere entirely. The distractor $\\frac{4928\\pi}{3}$ uses the cone formula $\\frac{1}{3}\\pi r^2 h$ with $h = r = 8$ instead of the hemisphere formula, giving $\\frac{512\\pi}{3}$ for the top piece: $1472\\pi + \\frac{512\\pi}{3} = \\frac{4928\\pi}{3}$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20A2JNE', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Paleontologist Mary Schweitzer''s 2005 discovery of soft tissue inside a Tyrannosaurus rex femur initially met with widespread skepticism, as prevailing models held that organic material could not survive for 68 million years. Subsequent laboratory analyses confirmed the presence of collagen proteins and blood vessel structures within the specimen. ______ some scientists proposed that iron from hemoglobin might act as a natural preservative, enabling soft-tissue persistence over geological timescales.', $lyceon_json$[{"key":"A","text":"To explain this phenomenon,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"In summary,"}]$lyceon_json$::jsonb, 'A', NULL, E'After the passage establishes that soft tissue was confirmed inside the fossil — a surprising finding that contradicts prevailing models — the final sentence introduces a hypothesis about how such preservation could occur. "To explain this phenomenon" correctly signals that what follows is a proposed mechanism for the confirmed but unexpected finding. "By contrast" implies the iron hypothesis opposes the confirmation of soft tissue, but it actually seeks to account for it. "Similarly" suggests an analogous situation, yet the iron hypothesis is an explanatory proposal rather than a parallel discovery. "In summary" indicates the passage is restating prior points, whereas the final sentence introduces new explanatory content not previously mentioned.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW212YMVD', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Archaeometallurgist Miljana Radivojević has challenged the long-held assumption that copper smelting was invented once in the ancient Near East and then diffused outward. By analyzing slag residues from Belovode, a Vinča culture settlement in present-day Serbia dated to approximately 5000 BCE, she demonstrated that the metallurgical techniques used there — including the deliberate use of oxidizing conditions to separate copper from ore — differed fundamentally from those documented at roughly contemporary Near Eastern sites such as Tal-i Iblis in Iran. At Tal-i Iblis, smelters relied on reducing atmospheres and different flux materials. Radivojević argues that these technical differences, combined with the absence of archaeological evidence for contact between the Vinča and Near Eastern communities during this period, indicate that ________', $lyceon_json$[{"key":"A","text":"copper smelting was developed independently in at least two separate regions rather than spreading from a single point of origin."},{"key":"B","text":"the Vinča culture possessed a more advanced understanding of metallurgy than any contemporary Near Eastern society."},{"key":"C","text":"copper smelting technology was transmitted from southeastern Europe to the Near East rather than in the opposite direction."},{"key":"D","text":"oxidizing smelting conditions produce higher-quality copper than reducing conditions, explaining why the Vinča technique eventually prevailed."}]$lyceon_json$::jsonb, 'A', NULL, E'Radivojević''s evidence shows fundamentally different techniques at two geographically separated, roughly contemporary sites with no evidence of contact. The logical conclusion is that copper smelting was developed independently in at least two regions, contradicting the single-origin diffusion model. The option claiming Vinča had a more advanced understanding introduces a qualitative hierarchy the passage does not establish; the text describes different techniques, not superior ones. The option proposing transmission from Europe to the Near East merely reverses the diffusion direction rather than supporting the independent-invention argument the evidence points toward. The option about oxidizing conditions producing higher-quality copper introduces a quality comparison absent from the passage and fabricates a claim about one technique prevailing over the other.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22PE8I3', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the site supervisor nor the three junior archaeologists _______ able to determine the precise age of the obsidian blade fragment recovered from Stratum VII, so the team shipped it to a laboratory in Tucson for obsidian hydration dating.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"were"},{"key":"C","text":"has been"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'B', NULL, E'In a ''neither...nor'' construction, the verb agrees with the subject closer to it. Here, ''the three junior archaeologists'' is the closer subject and is plural, so the plural verb ''were'' is correct. Using ''was'' incorrectly applies singular agreement, treating ''supervisor'' as the controlling subject rather than ''archaeologists.'' Using ''has been'' is singular and also shifts to the present perfect tense, which conflicts with the past-tense context established by ''shipped.'' Using ''is'' is singular and present tense, which disagrees with both the plural nearer subject and the past-tense narrative of the passage.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW23XC491', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The playwright Lorraine Hansberry drew on her family''s experiences with housing discrimination in 1930s Chicago to craft narratives that ______ the systemic barriers faced by Black families. Rather than depicting these struggles abstractly, she grounded them in the particularities of domestic life.', $lyceon_json$[{"key":"A","text":"illuminated"},{"key":"B","text":"fabricated"},{"key":"C","text":"obscured"},{"key":"D","text":"demolished"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states Hansberry drew on real experiences and grounded struggles in domestic life, indicating her narratives shed light on systemic barriers. The word meaning ''revealed or made clear'' fits logically. ''Fabricated'' means invented or made up, contradicting the passage''s emphasis on real experiences. ''Obscured'' means concealed or made unclear, which is the opposite of the passage''s meaning. ''Demolished'' means destroyed, which does not coherently describe what narratives do to barriers in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28CAN2F', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 1953, biochemist Mildred Cohn used oxygen-18 isotope tracing to demonstrate how ATP donates phosphate groups during enzymatic reactions. By the time the Swedish Academy recognized her contributions with the Garvan-Olin Medal in 1963, Cohn _______ the technique to more than forty different enzyme systems.', $lyceon_json$[{"key":"A","text":"has applied"},{"key":"B","text":"had applied"},{"key":"C","text":"was applying"},{"key":"D","text":"applied"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence describes an action (applying the technique to forty enzyme systems) that was completed before another past event (receiving the medal in 1963). The past perfect tense ''had applied'' correctly indicates an action completed before a specific point in the past. The present perfect ''has applied'' incorrectly links a past action to the present, which conflicts with the firmly past time frame of 1963. The past progressive ''was applying'' implies the action was ongoing at the moment of the award, rather than already completed. The simple past ''applied'' fails to establish the sequence — it does not clarify that the application of the technique preceded the recognition.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28QUN1N', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the late nineteenth century, the Brazilian composer Chiquinha Gonzaga challenged social conventions by performing in public venues typically reserved for male musicians. ______ her compositions blended European dance forms with Afro-Brazilian rhythmic patterns, creating a hybrid style that predated bossa nova by several decades.', $lyceon_json$[{"key":"A","text":"Meanwhile,"},{"key":"B","text":"In addition,"},{"key":"C","text":"On the contrary,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage presents two parallel facts about Gonzaga: she challenged social conventions by performing publicly, and her compositions created a hybrid musical style. These are additive points about her significance, so "In addition" correctly signals supplementary information. "Meanwhile" suggests simultaneous but separate events or actors, yet both facts concern the same person. "On the contrary" signals a reversal or contradiction, but the second clause does not oppose the first. "As a result" implies causation, yet her compositional style is not presented as a consequence of performing in male-dominated venues.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EBLS8G', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Stavanger in Norway have found that the physical act of handwriting activates brain regions associated with memory consolidation more robustly than typing on a keyboard does. In a 2023 study, thirty-seven participants wrote words by hand and typed them while undergoing electroencephalography (EEG) scans. The handwriting condition produced significantly stronger connectivity patterns in the parietal and central brain regions, areas linked to sensory-motor integration and memory encoding. The researchers concluded that the fine motor movements required to form each letter by hand create neural pathways that reinforce learning in ways that the uniform keystrokes of typing do not.', $lyceon_json$[{"key":"A","text":"Handwriting engages brain regions involved in memory more effectively than typing does."},{"key":"B","text":"EEG technology has advanced to the point where it can detect differences between handwriting and typing."},{"key":"C","text":"Fine motor skills are declining among adults who rely on keyboards for most written communication."},{"key":"D","text":"The University of Stavanger has become a leading center for neuroscience research in Europe."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the finding that handwriting activates memory-related brain regions more strongly than typing. The option stating that handwriting engages brain regions involved in memory more effectively than typing captures this central idea. The option about EEG technology focuses on the study''s tool rather than its conclusion, misreading a detail as the main point. The option about declining fine motor skills introduces a claim the passage never makes, overreaching beyond the text. The option about the university''s reputation is an unsupported detail that mistakes the institution for the subject of the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ELLYZR', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'The fruit fly Drosophila melanogaster has been a model organism in genetics research since Thomas Hunt Morgan''s early twentieth-century experiments. One reason for its enduring usefulness is its remarkably short generation time: a new generation can be produced roughly every twelve days under standard laboratory conditions. This rapid reproduction allows researchers to observe the effects of genetic mutations across many generations within a single academic year. By contrast, studying equivalent generational changes in mammals such as mice, which have a generation time of approximately ten weeks, would require ________', $lyceon_json$[{"key":"A","text":"significantly more time to accumulate a comparable number of generations."},{"key":"B","text":"fewer genetic mutations to appear in each successive generation."},{"key":"C","text":"a larger number of individual organisms per experimental cohort."},{"key":"D","text":"less precise instruments for tracking inherited traits."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that fruit flies are useful because their short generation time allows many generations to be observed quickly. The logical completion contrasts this with mice, whose longer generation time means researchers would need significantly more time to accumulate a comparable number of generations. The option about fewer mutations appearing per generation introduces a biological claim not supported by the passage''s discussion of generation time. The option about larger cohort sizes addresses experimental design factors unrelated to the generation-time comparison the passage sets up. The option about less precise instruments is entirely unconnected to the passage''s point about the speed of generational turnover.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FEHUSL', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a report about global food security initiatives. Which choice most effectively introduces the Svalbard Global Seed Vault to an audience unfamiliar with the facility?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FH0V2N', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Researchers studying the migration patterns of Arctic terns found that these birds travel roughly 71,000 kilometers each year. The sheer magnitude of this journey ______ even seasoned ornithologists, who had previously underestimated the distances involved.', $lyceon_json$[{"key":"A","text":"astonished"},{"key":"B","text":"frightened"},{"key":"C","text":"offended"},{"key":"D","text":"detained"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes researchers who had underestimated the distances and were struck by the magnitude of the journey. The word meaning ''greatly surprised'' fits this context precisely. ''Frightened'' implies fear, which is not supported by the passage. ''Offended'' implies insult or moral affront, which has no basis in the context. ''Detained'' means physically held or delayed, which is incoherent with a discovery about distance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FSLPKO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Restoration ecologist Tomás Herrera has reintroduced native tallgrass species to 3,100 acres of degraded prairie in _______ the replanted parcels now support breeding populations of Henslow''s sparrows, a grassland bird whose numbers declined by sixty-seven percent between 1966 and 2019.', $lyceon_json$[{"key":"A","text":"Kansas; as a result,"},{"key":"B","text":"Kansas, as a result,"},{"key":"C","text":"Kansas as a result,"},{"key":"D","text":"Kansas; in addition,"}]$lyceon_json$::jsonb, 'A', NULL, E'The blank separates two independent clauses: one about Herrera''s reintroduction of tallgrass and one about the replanted parcels supporting sparrow populations. The second clause describes a consequence of the first, so the conjunctive adverb ''as a result'' correctly conveys the cause-effect relationship. A semicolon before ''as a result'' and a comma after it is the standard punctuation for joining independent clauses with a conjunctive adverb. Using a comma before ''as a result'' creates a comma splice — two independent clauses joined only by a comma and a conjunctive adverb, which is not equivalent to using a coordinating conjunction. Omitting all punctuation before ''as a result'' creates a run-on sentence. Using ''in addition'' with a semicolon provides correct boundary mechanics but misrepresents the logical relationship: the sparrow recovery is a direct consequence of the tallgrass restoration, not a separate, additional fact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HOGPSB', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Zuni people of western New Mexico have long crafted intricate inlay jewelry from turquoise, jet, and coral. In the 1920s, lapidary artist Leekya Deyuse pioneered a style of carved fetish _______ small animal figures, painstakingly shaped from single stones, became sought-after collectibles among traders and museum curators alike.', $lyceon_json$[{"key":"A","text":"necklaces, his"},{"key":"B","text":"necklaces. His"},{"key":"C","text":"necklaces his"},{"key":"D","text":"necklaces, so his"}]$lyceon_json$::jsonb, 'B', NULL, E'The blank separates two independent clauses: one about Deyuse pioneering a style and one about his figures becoming collectibles. A period correctly separates these two independent clauses into distinct sentences. Using a comma before ''his'' creates a comma splice, fusing two independent clauses with only a comma. Omitting all punctuation creates a run-on sentence. Using a comma with ''so'' incorrectly implies a cause-effect relationship — the figures did not become collectibles because Deyuse pioneered the style; rather, the second sentence provides additional detail about a different outcome.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2HXILXZ', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 monograph on Ottoman court architecture, historian Zeynep Celik argued that Western scholars have long ______ the sophistication of non-European building traditions by evaluating them exclusively through the lens of Greco-Roman aesthetics, thereby reducing complex spatial innovations to mere curiosities.', $lyceon_json$[{"key":"A","text":"underrated"},{"key":"B","text":"catalogued"},{"key":"C","text":"replicated"},{"key":"D","text":"consolidated"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes scholars reducing complex innovations to ''mere curiosities'' by applying an inappropriate evaluative framework, indicating they have failed to appreciate the sophistication. The word meaning ''failed to recognize the full value of'' fits precisely. ''Catalogued'' means systematically listed or classified, which does not convey the negative evaluative judgment described. ''Replicated'' means copied or reproduced, which is incoherent with the idea of misjudging sophistication. ''Consolidated'' means combined or strengthened, which does not describe the act of diminishing something''s perceived value.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LNHLL0', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Every autumn, the municipal arborist inspects the elm trees along Crescent Boulevard. This year, the arborist noted that one of the oldest _______ signs of Dutch elm disease in its upper canopy.', $lyceon_json$[{"key":"A","text":"trees show"},{"key":"B","text":"trees shows"},{"key":"C","text":"trees have shown"},{"key":"D","text":"trees are showing"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the verb is ''one,'' not ''trees.'' Since ''one'' is singular, the verb must also be singular: ''shows.'' Using ''show'' incorrectly treats ''trees'' as the subject, producing a subject-verb agreement error. Using ''have shown'' pairs a plural auxiliary with the singular subject ''one,'' creating the same agreement error with an unnecessary shift to present perfect tense. Using ''are showing'' pairs a plural auxiliary with the singular subject ''one,'' again producing a subject-verb agreement error.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MPP0XF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Economists have traditionally modeled household savings behavior using rational-agent frameworks that assume individuals optimize their long-term financial outcomes. Under these models, people save more when interest rates rise because higher returns make future consumption more attractive relative to present spending.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MRKIJJ', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Marine biologist Keira Okonjo has spent seventeen years studying bioluminescent organisms in the Mariana _______ her team recently identified a previously unknown species of lanternfish that emits a distinctive violet glow at depths exceeding 1,400 meters.', $lyceon_json$[{"key":"A","text":"Trench, and"},{"key":"B","text":"Trench and"},{"key":"C","text":"Trench. And"},{"key":"D","text":"Trench, and,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence joins two independent clauses: one about Okonjo''s years of study and one about her team''s recent discovery. A comma followed by the coordinating conjunction ''and'' correctly links two independent clauses. Omitting the comma before the coordinating conjunction creates a run-on when joining two full independent clauses. Using a period before ''And'' unnecessarily splits two closely related clauses about the same researcher''s work into separate sentences, weakening cohesion. A comma plus coordinating conjunction is the standard method for joining related independent clauses. Adding a comma after ''and'' introduces an unnecessary and incorrect comma that disrupts the flow between the conjunction and the second clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NWKKSD', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the relationship between the two phenomena discussed in the text?', E'Marine biologist Sylvia Earle has drawn attention to a little-appreciated feedback loop in ocean ecosystems. Phytoplankton, microscopic photosynthetic organisms drifting near the surface, absorb roughly forty percent of the carbon dioxide removed from the atmosphere each year. These organisms depend on nutrients — particularly iron and nitrogen — that are recycled upward from the deep ocean by whale excrement. As commercial whaling in the twentieth century reduced large whale populations by an estimated sixty-seven to ninety percent, the vertical nutrient cycle weakened. Earle notes that the resulting decline in phytoplankton density not only diminished the ocean''s capacity to sequester carbon but also reduced oxygen production, since phytoplankton generate approximately half of the planet''s atmospheric oxygen. The ecological cost of whale depletion, she argues, therefore extends well beyond the loss of the whales themselves.', $lyceon_json$[{"key":"A","text":"The decline of whale populations disrupted a nutrient cycle that phytoplankton require, which in turn reduced the ocean's ability to absorb carbon dioxide and produce oxygen."},{"key":"B","text":"Phytoplankton produce oxygen that whales need to survive, and as phytoplankton populations declined, whale populations declined as well."},{"key":"C","text":"Commercial whaling directly reduced phytoplankton populations by disturbing their surface habitat, which subsequently lowered atmospheric oxygen levels."},{"key":"D","text":"Whales consume large quantities of phytoplankton, so removing whales from the ecosystem allowed phytoplankton populations to grow unchecked."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a feedback loop: whales provide nutrients (through excrement) that phytoplankton need, and phytoplankton in turn absorb carbon dioxide and produce oxygen. When whale populations dropped, the nutrient cycle weakened, reducing phytoplankton density and thus both carbon sequestration and oxygen production. The option connecting whale decline to nutrient-cycle disruption and subsequent reductions in carbon absorption and oxygen production captures this relationship accurately. The option suggesting phytoplankton produce oxygen whales need reverses the causal chain described in the passage; it was the whales that supported phytoplankton, not the other way around in the feedback loop discussed. The option about whaling directly disturbing phytoplankton habitat misrepresents the mechanism; the passage describes an indirect effect through nutrient deprivation, not direct habitat disturbance. The option about whales consuming phytoplankton contradicts the passage, which states whales fertilize phytoplankton through their excrement rather than eating them.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O2QIYF', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Urban planner Mariana Vega has argued that converting street parking spaces into small parklets — miniature public parks with seating and greenery — reliably increases foot traffic to neighboring businesses. She points to a 2021 survey of 130 shop owners along repurposed corridors in Bogota, in which 78% reported higher customer volume after parklet installation.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OP8P9H', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Dendrochronologist Fatima al-Rashidi extracted core samples from bristlecone pines in the White Mountains of eastern _______ she cross-referenced the ring patterns against a 9,700-year regional chronology to pinpoint a severe drought episode that had previously gone undetected in the archaeological record.', $lyceon_json$[{"key":"A","text":"California; consequently,"},{"key":"B","text":"California, she"},{"key":"C","text":"California. She"},{"key":"D","text":"California; moreover,"}]$lyceon_json$::jsonb, 'C', NULL, E'The blank separates two independent clauses. Starting a new sentence with ''She'' correctly separates the two actions as sequential steps without implying a cause-effect or additive relationship. Using a semicolon with ''consequently'' incorrectly implies that extracting samples caused the cross-referencing; the two are sequential steps in a process, not a cause and its consequence. Using a comma before ''she'' creates a comma splice, fusing two independent clauses with only a comma. Using a semicolon with ''moreover'' incorrectly implies the second clause adds a separate, additional point, when it actually describes the next step performed on the same samples.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PUTKJ9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The paintings of Hilma af Klint, a Swedish artist who created large-scale abstract compositions beginning in 1906 — well before Kandinsky or Mondrian pursued similar _______ only recently received widespread critical attention, partly because af Klint stipulated that the works not be exhibited until twenty years after her death.', $lyceon_json$[{"key":"A","text":"work, have"},{"key":"B","text":"work — have"},{"key":"C","text":"work have"},{"key":"D","text":"work, they have"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence contains a long parenthetical aside set off by an em dash after ''similar.'' To properly close the parenthetical interruption, a matching em dash is needed before returning to the main clause. Using ''work — have'' correctly closes the dash pair and continues the main clause with the verb ''have,'' which agrees with the plural subject ''paintings.'' Using a comma instead of a closing dash creates a mismatched punctuation pair, since the parenthetical was opened with a dash. Omitting both the dash and any punctuation leaves the parenthetical unclosed, making the sentence structurally ungrammatical. Inserting a comma and the pronoun ''they'' before ''have'' not only fails to close the dash but also creates a comma splice and an unnecessary pronoun, since ''paintings'' is already the subject.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S3IQ8E', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Helsinki have found that certain species of Arctic lichen can survive temperatures as low as negative 196 degrees Celsius. ______ these organisms are among the most cold-tolerant life forms ever documented.', $lyceon_json$[{"key":"A","text":"In other words,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Consequently,"}]$lyceon_json$::jsonb, 'D', NULL, E'The second clause draws a conclusion from the finding described in the first clause: because certain lichens survive extremely low temperatures, they rank among the most cold-tolerant organisms. The transition "Consequently" correctly signals this cause-and-effect relationship. "In other words" would signal a restatement, but the second clause adds a new evaluative claim rather than restating the first. "Nevertheless" implies contrast, yet no opposition exists between the two clauses. "For instance" introduces an example, but the second clause is a generalization about the organisms, not a specific illustrative case.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S8U9B1', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'A team of entomologists at the Federal University of Viçosa in Brazil hypothesized that the sharp decline of native stingless bee populations in the Atlantic Forest region is driven primarily by competition with the invasive Africanized honeybee, which forages more aggressively and monopolizes floral resources. To test this, the researchers plan to compare stingless bee colony health metrics in forest fragments where Africanized honeybees are present versus fragments where they are absent.', $lyceon_json$[{"key":"A","text":"Stingless bee colonies in fragments without Africanized honeybees show higher brood production and greater pollen stores than colonies in fragments where Africanized honeybees are present."},{"key":"B","text":"Africanized honeybees in the Atlantic Forest region produce more honey per colony than stingless bees do."},{"key":"C","text":"Stingless bee populations have declined in urban areas where pesticide use has increased over the past decade."},{"key":"D","text":"Africanized honeybees were first introduced to Brazil in 1956 and have since spread across most of South America."}]$lyceon_json$::jsonb, 'A', NULL, E'The researchers hypothesize that Africanized honeybee competition drives stingless bee decline. Evidence that stingless bee colonies are healthier where Africanized honeybees are absent directly supports this claim by showing a correlation between the competitor''s presence and reduced colony health. The finding about Africanized honeybees producing more honey concerns honeybee productivity, not the competitive impact on stingless bees, so it does not address the hypothesis. The finding about pesticide-related declines in urban areas offers an alternative explanation unrelated to competition, making it irrelevant to the hypothesis about interspecies competition. The historical fact about when Africanized honeybees arrived in Brazil provides background context but does not demonstrate a competitive effect on stingless bee populations.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TJD5FC', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Based on the texts, how do the authors of Text 1 and Text 2 differ in their understanding of the role of fire in forest ecosystems?', E'Text 1: Ecologist Priya Chandrasekaran contends that periodic low-intensity fires are essential to the long-term health of temperate forests. Her seventeen-year study of ponderosa pine stands in central Oregon found that plots subjected to controlled burns every four to seven years exhibited 40% greater seedling recruitment and significantly lower rates of bark beetle infestation than unburned plots. She concludes that fire suppression policies have inadvertently weakened forest resilience.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TRWL13', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'When the French chemist Michel Chevreul published his 1839 treatise on color contrast, painters initially dismissed his findings as irrelevant to studio practice. Chevreul had demonstrated that adjacent colors alter each other''s appearance — a phenomenon he termed ''simultaneous contrast.'' Within two decades, however, Impressionist painters such as Claude Monet began deliberately juxtaposing complementary hues on their canvases, a technique that directly applied Chevreul''s principle. By the early twentieth century, color theorists in the Bauhaus movement were teaching Chevreul''s framework as foundational to visual design.', $lyceon_json$[{"key":"A","text":"It traces the gradual acceptance of a scientific idea by artistic communities over time."},{"key":"B","text":"It compares two competing scientific theories about visual perception."},{"key":"C","text":"It argues that scientific research is more rigorous than artistic experimentation."},{"key":"D","text":"It presents a chronological biography of a single scientist's career achievements."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage moves from initial dismissal of Chevreul''s findings by painters, to Impressionists adopting his principle, to Bauhaus theorists teaching it as foundational — tracing a trajectory of gradual acceptance over time. The option about comparing two competing theories is wrong because only one theory (simultaneous contrast) is discussed. The option about arguing scientific rigor is superior to artistic experimentation is wrong because no such evaluative claim is made. The option about presenting a chronological biography is wrong because the passage focuses on the reception of one idea, not on Chevreul''s full career.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UFQ6CL', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, which choice best describes a point of agreement and a point of disagreement between the two authors?', E'Text 1: Cognitive scientist Elena Marchetti proposes that bilingual individuals exhibit superior executive function not because managing two languages strengthens general cognitive control, as the ''bilingual advantage'' hypothesis suggests, but because bilinguals develop heightened metalinguistic awareness — an understanding of language as a system — that transfers selectively to tasks requiring rule detection and pattern analysis. She argues that studies failing to find a broad bilingual advantage in attention and inhibition actually support her narrower claim, since those tasks do not rely on metalinguistic reasoning.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W2OW8W', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively support the student''s claim?', E'A student writing a research paper argues that Nella Larsen''s 1929 novel Passing is primarily concerned with the instability of racial identity in early twentieth-century America rather than with the romantic jealousy between its two protagonists. The student is looking for a quotation from a literary critic to support this interpretation.', $lyceon_json$[{"key":"A","text":"\"Larsen constructs the friendship between Irene and Clare as a vehicle for exposing how racial categories in 1920s America were performative constructs rather than fixed biological realities.\""},{"key":"B","text":"\"The novel's lasting appeal rests on Larsen's skillful depiction of the tension between two women whose rivalry over a shared romantic interest drives the narrative to its tragic conclusion.\""},{"key":"C","text":"\"Passing is best understood as a work of domestic fiction in the tradition of Edith Wharton, focused on the manners and social rituals of a particular class.\""},{"key":"D","text":"\"Larsen's prose style, characterized by its spare, almost journalistic quality, marks a departure from the more ornate language of her Harlem Renaissance contemporaries.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The student''s claim focuses on the instability of racial identity as the novel''s primary concern. The quotation describing the friendship as a vehicle for exposing racial categories as performative constructs directly supports this reading of racial identity as unstable and socially constructed. The quotation emphasizing romantic rivalry as the narrative''s driver contradicts the student''s claim by centering jealousy rather than racial identity. The quotation placing the novel in a tradition of domestic fiction about class manners shifts attention to genre and social ritual, which does not address racial identity instability. The quotation about Larsen''s prose style discusses her literary technique, a topic unrelated to the student''s claim about racial identity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W2Y9R4', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary arguing that microplastic contamination poses previously unrecognized atmospheric risks. Which choice most effectively synthesizes the study''s findings to support this argument?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WXCE73', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'Coral reefs support roughly twenty-five percent of all known marine species despite covering less than one percent of the ocean floor. Marine biologists have long studied the nutrient cycling processes that sustain these ecosystems. Recent fieldwork off the coast of Papua New Guinea, however, revealed that certain deep-reef sponges filter organic particles at rates nearly triple those previously recorded, suggesting that existing models of reef nutrient budgets may significantly undercount sponge contributions.', $lyceon_json$[{"key":"A","text":"It introduces a finding that challenges an established scientific understanding."},{"key":"B","text":"It provides a definition of a technical term used later in the passage."},{"key":"C","text":"It summarizes the overall argument of the passage."},{"key":"D","text":"It describes the history of a particular research methodology."}]$lyceon_json$::jsonb, 'A', NULL, E'The final sentence reports new fieldwork results showing sponge filtration rates far exceed prior records, and it uses the word ''however'' to signal a contrast with previous understanding, thereby introducing a finding that challenges existing models. The option about defining a technical term is wrong because no term is defined in the sentence. The option about summarizing the overall argument is wrong because the sentence presents new evidence rather than restating a thesis. The option about describing research methodology history is wrong because the sentence reports results, not methods.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XKFBC2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Urban ecologist Paige Warren has studied how bird communities respond to the creation of green corridors — narrow strips of vegetation connecting larger parks — in cities with high levels of habitat fragmentation. Warren found that within three years of corridor establishment, species richness in the connected parks increased by an average of twenty-three percent, with the greatest gains among insectivorous species that require large foraging territories. Warren attributes this pattern to the corridors'' role in enabling movement between habitat patches. However, she cautions that corridors also facilitated the spread of brood parasites such as the brown-headed cowbird, which lays its eggs in other birds'' nests. This suggests that while green corridors can enhance urban biodiversity, ________', $lyceon_json$[{"key":"A","text":"they may simultaneously introduce ecological pressures that threaten some of the species they are intended to protect."},{"key":"B","text":"their positive effects on species richness are likely to diminish completely within a decade of installation."},{"key":"C","text":"they are more effective at supporting plant diversity than bird diversity in fragmented urban landscapes."},{"key":"D","text":"insectivorous species will eventually outcompete brood parasites for nesting sites along the corridors."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a trade-off: corridors increase species richness but also facilitate the spread of brood parasites that harm other birds. The logical conclusion is that corridors may introduce ecological pressures threatening some of the species they were designed to help. The option about positive effects diminishing completely within a decade goes far beyond the passage, which describes a concurrent risk rather than a total reversal over time. The option about plant diversity versus bird diversity introduces a comparison the passage never addresses. The option about insectivorous species outcompeting brood parasites for nesting sites invents a competitive dynamic not discussed or implied in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XV2IW4', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the scientists'' conclusion?', E'Geochemists analyzing sediment cores from Lake Petén Itzá in Guatemala concluded that a prolonged drought between roughly 800 and 1000 CE was the primary driver of the Classic Maya collapse. Their evidence rests on elevated ratios of oxygen-18 to oxygen-16 isotopes in calcium carbonate layers deposited during that period — ratios that indicate reduced rainfall. The scientists acknowledge that political fragmentation and warfare also intensified during this interval but maintain that these social disruptions were themselves consequences of agricultural failure caused by drought.', $lyceon_json$[{"key":"A","text":"Inscriptions at several major Maya sites record escalating interstate warfare beginning around 740 CE, decades before the oxygen-isotope ratios indicate drought conditions began."},{"key":"B","text":"The oxygen-18 to oxygen-16 ratio method has been validated by independent studies at lakes in other tropical regions."},{"key":"C","text":"Some Maya cities in the northern Yucatán continued to thrive during the 800–1000 CE period, showing population growth and new monumental construction."},{"key":"D","text":"Tree-ring records from the region confirm that rainfall was below average between 800 and 1000 CE."}]$lyceon_json$::jsonb, 'A', NULL, E'The scientists conclude that drought caused social disruptions, not the reverse. If inscriptions show interstate warfare beginning decades before the drought, the timeline contradicts the causal sequence the scientists propose, directly undermining their conclusion that political fragmentation was a consequence of drought. The finding validating the oxygen-isotope method strengthens rather than undermines the scientists'' evidence base, so it works against the question''s goal. The finding about some northern cities thriving is partially relevant but does not directly challenge the causal claim about drought driving collapse; it could be explained by regional variation in rainfall or other local factors. The finding about tree-ring records confirming below-average rainfall corroborates the drought data, which supports rather than undermines the conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Z02P9X', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason Lourdes Benería argues that conventional GDP measurements are inadequate?', E'Economist Lourdes Benería has spent decades challenging the way national economic output is calculated. In her view, conventional gross domestic product figures systematically undervalue certain forms of labor because they count only market transactions — goods and services exchanged for money. Unpaid domestic work, subsistence farming, and community caregiving, Benería contends, generate real economic value but are excluded from official tallies. She points out that in many lower-income nations, unpaid labor accounts for a share of total productive activity roughly equal to the formal economy, yet policymakers who rely on GDP data alone remain unaware of this contribution. Without recognizing these activities, Benería warns, governments risk designing economic policies that fail to support the populations most responsible for sustaining households and communities.', $lyceon_json$[{"key":"A","text":"GDP figures fail to account for productive activities that occur outside market transactions."},{"key":"B","text":"GDP calculations overestimate the value of goods produced in lower-income nations."},{"key":"C","text":"Policymakers in lower-income nations deliberately exclude subsistence farming from economic data."},{"key":"D","text":"Community caregiving has increased as a proportion of economic activity in recent decades."}]$lyceon_json$::jsonb, 'A', NULL, E'Benería''s central criticism is that GDP counts only market transactions, thereby excluding unpaid domestic work, subsistence farming, and caregiving that generate real economic value. The option about GDP failing to account for productive activities outside market transactions directly captures this reasoning. The option about overestimating goods in lower-income nations reverses the direction of Benería''s critique; she argues these nations'' output is undervalued, not overestimated. The option about policymakers deliberately excluding subsistence farming attributes intentional action where the passage describes an inadvertent consequence of the GDP framework. The option about caregiving increasing over time introduces a temporal trend the passage never discusses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZHHRYJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban ecologist Paige Warren has documented that bird species richness in Phoenix, Arizona, peaks not in the city''s few remaining desert preserves but in moderately landscaped residential neighborhoods, where irrigated lawns and ornamental trees create resource patches absent from the surrounding arid terrain. ______ Warren cautions that this elevated richness is taxonomically skewed: the neighborhoods attract generalist species such as house sparrows and great-tailed grackles while displacing desert specialists like the cactus wren and curve-billed thrasher.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"However,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first clause presents a seemingly positive finding — bird species richness peaks in landscaped neighborhoods rather than desert preserves. The second clause introduces a complication: this richness is "taxonomically skewed," favoring generalists over desert specialists. The transition "However" correctly signals this shift from an ostensibly favorable observation to a qualifying concern. "Furthermore" would add a supporting point, but the second clause qualifies rather than reinforces the first. "Specifically" would introduce a detailed elaboration of the same point, yet the second clause introduces a contrasting dimension (taxonomic composition versus raw richness). "Accordingly" implies the second clause follows logically as a consequence, but Warren''s caution works against the initial finding rather than extending it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ZQ3RP5', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student wants to emphasize how Kéré''s background shaped his architectural philosophy. Which choice most effectively accomplishes this goal?', E'Notes:
